.ax-f-mid{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ax-f-mid .course-tag-pill{display:inline-flex;align-items:center;gap:4px;font-size:13px;font-weight:600;color:var(--ink);background:rgba(157,184,255,.4);padding:3px 10px;transform:rotate(-1.5deg);cursor:pointer;border:0}
.ax-f-mid .add-course-tag-btn{border:1.5px dashed #C9D1E1;border-radius:4px;background:none;font-family:var(--hand);font-size:17px;color:var(--soft);padding:2px 10px;cursor:pointer;min-height:32px}
.ax-prog{display:flex;flex-direction:column;gap:6px}
.ax-prog span{font-family:var(--hand);font-size:18px;color:var(--ink)}
.ax-prog i{position:relative;display:block;height:7px;border-radius:4px;background:#E6E9F0;overflow:hidden}
.ax-prog i b{position:absolute;left:0;top:0;bottom:0;background:repeating-linear-gradient(-45deg,#2F6BFF 0 8px,#5B8CFF 8px 16px);border-radius:4px;transition:width .6s var(--ease)}
