@keyframes axStripe{to{background-position:22px 0}}
.ax-fail{font-family:var(--hand);font-size:18px;color:var(--red)}
.ax-f-foot{display:flex;align-items:center;gap:6px;padding-top:10px;border-top:1.5px dashed #DCE2EE}
.ax-f-foot .ax-btn{min-height:40px;padding:6px 14px;font-size:14px}
.ax-f-foot .sp{flex:1}
.ax-iconbtn{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border:0;border-radius:6px;background:none;color:var(--soft);cursor:pointer}
.ax-iconbtn:hover{background:#EEF1F6;color:var(--navy)}
.ax-iconbtn.del:hover{color:var(--red);background:#FFF1EF}
.ax-iconbtn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.ax-iconbtn:focus-visible{outline:2px solid var(--blue);outline-offset:1px}
.ax-vers{display:flex;flex-direction:column;gap:2px;font-size:13.5px}
.ax-vers a{color:var(--ink);text-decoration:underline;text-underline-offset:3px;padding:3px 0}
.ax-resum{align-self:flex-start;border:0;background:none;padding:2px 0;font-family:var(--hand);font-size:18px;color:var(--blue);cursor:pointer;text-decoration:underline;text-decoration-style:wavy;text-decoration-color:#C9D6FF;text-underline-offset:4px}
#docs-view #bulk-delete-bar{top:76px!important;border:2px solid var(--navy)!important;border-radius:8px!important;background:#FFFEFB!important;box-shadow:0 20px 30px -20px rgba(13,24,56,.6)!important}
#docs-view #bulk-delete-bar .btn{border-radius:6px!important}

/* ================= BÖLÜM AKIŞI (feed) ================= */
.ax-feed-wrap{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px;align-items:start;margin-top:18px}
.ax-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}
.ax-chips .ax-tape{cursor:pointer;border:0;font:inherit;font-size:14.5px;font-weight:600;min-height:34px}
.ax-chips .ax-tape[aria-pressed="true"]{background:var(--navy);color:#fff}
.ax-chips .ax-tape:focus-visible{outline:2px solid var(--blue);outline-offset:2px}
.ax-board{position:relative;padding:28px 26px 34px;border:12px solid #C9CED9;border-image:linear-gradient(135deg,#DDE1EA,#AEB6C6) 1;background:#B88C5A;background-image:var(--cork);background-size:160px;box-shadow:inset 0 0 30px rgba(60,35,10,.35),0 30px 40px -30px rgba(13,24,56,.6);min-height:420px}
