.ax-pin:nth-child(3n)::before{background:radial-gradient(circle at 35% 30%,#9BE3BE,#1E8A55 55%,#0E4D2E)}
.ax-pin-who{display:flex;align-items:center;gap:10px;margin:0 0 12px -28px}
.ax-av{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;flex:none;border-radius:50%;background:#E6EBF5;border:2px solid #fff;box-shadow:0 2px 4px rgba(0,0,0,.25);font-family:var(--disp);font-weight:800;font-size:14px;color:var(--navy);overflow:hidden}
.ax-av img{width:100%;height:100%;object-fit:cover}
.ax-pin-who b{display:block;font-size:15px;line-height:1.1;color:var(--navy)}
