.ax-pin-who .ax-tape{margin-left:auto;font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;padding:3px 8px;text-transform:uppercase}
.ax-pin .lbl{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;color:var(--blue)}
.ax-pin h4{margin:2px 0 8px;font-size:19px;line-height:1.2;font-weight:800;word-break:break-word}
.ax-pin p{font-size:15px;line-height:28px;color:#2A3A66}
.ax-pin-foot{display:flex;align-items:center;gap:10px;margin-top:12px;flex-wrap:wrap}
.ax-pin-foot .ax-link{font-family:var(--hand);font-size:20px}
.ax-vote{display:inline-flex;align-items:center;gap:7px;min-height:38px;padding:4px 12px;margin-left:auto;border:1.5px solid #C9D1E1;border-radius:20px;background:#fff;font:inherit;font-size:14px;font-weight:600;color:var(--ink);cursor:pointer;transition:background .2s,border-color .2s}
.ax-vote svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.ax-vote[aria-pressed="true"]{background:var(--navy);border-color:var(--navy);color:#fff}
.ax-vote[aria-pressed="true"] svg{fill:#FFD966;stroke:#FFD966}
.ax-vote:focus-visible{outline:2px solid var(--blue);outline-offset:2px}
.ax-board-empty{margin:40px auto 10px;max-width:420px;padding:24px 26px 22px;background:#FFF1BF;transform:rotate(-1.5deg);box-shadow:0 26px 26px -22px rgba(0,0,0,.6);text-align:center;color:var(--navy)}
.ax-board-empty b{display:block;font-family:var(--hand);font-size:30px;font-weight:700}
.ax-board-empty p{margin:6px 0 14px!important;font-size:15px}
.ax-roll{padding:20px 18px 14px 34px;background:#FFFEFB;background-image:linear-gradient(90deg,transparent 22px,rgba(201,72,59,.35) 22px,rgba(201,72,59,.35) 23.5px,transparent 23.5px);border:1px solid #E6E2D6;box-shadow:0 20px 30px -28px rgba(13,24,56,.6)}
.ax-roll h3{margin:0;font-family:var(--hand);font-weight:700;font-size:28px;color:var(--ink);letter-spacing:0}
.ax-roll > small{display:block;font-family:var(--hand);font-size:18px;color:var(--soft);margin-bottom:8px}
.ax-roll ul{list-style:none;margin:0;padding:0}
.ax-roll li{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #EEF1F6}
.ax-roll li .ax-av{width:32px;height:32px;font-size:12px}
.ax-roll li b{display:block;font-size:14.5px;color:var(--navy)}
.ax-roll li small{display:block;font-size:12px;color:var(--soft)}
.ax-roll .none{font-family:var(--hand);font-size:19px;color:var(--soft);padding:6px 0}
.ax-more{display:flex;justify-content:center;margin-top:26px}
@media (max-width: 1100px){.ax-feed-wrap{grid-template-columns:1fr}}
@media (max-width: 560px){.ax-board{padding:20px 12px 26px;border-width:8px}.ax-pins{grid-template-columns:1fr}.ax-pin{padding-left:40px}}

/* ================= BİLGİ KARTLARI (cards) ================= */
.ax-cards-tools{display:flex;align-items:center;gap:12px 18px;flex-wrap:wrap;margin-top:18px}
.ax-cards-tools .cards-status-chips{display:flex;gap:6px;margin:0}
.ax-cards-tools .cards-status-chip{min-height:38px;padding:6px 14px;border:1.5px solid #D7DDE9;border-radius:7px 7px 0 0;border-bottom-width:0;background:#EEF1F6;font-family:var(--hand);font-weight:600;font-size:20px;color:var(--ink);cursor:pointer;transform:translateY(3px)}
.ax-cards-tools .cards-status-chip.active{background:#FFF1BF;transform:none;color:var(--navy)}
.ax-cards-tools label{font-size:13.5px;font-weight:600;color:var(--muted)}
.ax-cards-tools .ax-sp{flex:1}
.ax-cards-tools #btn-clear-filters{display:none}
#cards-view .search-container{margin:0}
#cards-view #cards-search{width:260px}
.ax-lib{display:grid;grid-template-columns:300px minmax(0,1fr);gap:26px;align-items:start;margin-top:18px}
.ax-decks{display:flex;flex-direction:column;gap:18px;max-height:calc(100vh - 160px);overflow:auto;padding:12px 6px 8px 2px;position:sticky;top:80px}
.ax-dbox{position:relative;display:block;width:100%;padding:28px 16px 14px;border:0;background:var(--navy);border-radius:4px 4px 8px 8px;color:#fff;text-align:center;cursor:pointer;box-shadow:0 20px 24px -20px rgba(13,24,56,.8);font:inherit;transition:transform .25s var(--ease)}
.ax-dbox::before{content:"";position:absolute;left:4px;right:4px;top:-12px;height:16px;background:#24346A;border-radius:4px 4px 0 0;transform:rotate(-1.2deg)}
.ax-dbox:hover{transform:translateY(-2px)}
.ax-dbox[aria-current="true"]{box-shadow:0 0 0 3px #FFD966,0 20px 24px -20px rgba(13,24,56,.8)}
.ax-dbox:focus-visible{outline:3px solid var(--blue);outline-offset:3px}
.ax-dbox .lab{display:inline-block;max-width:100%;padding:8px 16px 6px;background:#fff;color:var(--navy);box-shadow:0 4px 6px -4px rgba(0,0,0,.5);transform:rotate(-1deg)}
.ax-dbox .lab b{display:block;font-family:var(--hand);font-size:25px;font-weight:700;line-height:1.05;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:220px}
.ax-dbox .lab small{display:block;font-size:12px;color:var(--soft)}
.ax-dbox .tags{display:flex;justify-content:center;flex-wrap:wrap;gap:5px;margin-top:12px}
.ax-dbox .tags span{font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;padding:2px 6px;border:1px solid rgba(255,255,255,.35);border-radius:2px;text-transform:uppercase}
.ax-dbox .pr{display:flex;align-items:center;gap:8px;margin-top:12px;padding-top:10px;border-top:1px dashed rgba(255,255,255,.25);font-family:var(--hand);font-size:18px;color:#C9D4EE}
.ax-dbox .pr i{flex:1;height:5px;border-radius:3px;background:rgba(255,255,255,.18);overflow:hidden}
.ax-dbox .pr i b{display:block;height:100%;background:#4ED68F}
.ax-dbox .sh{position:absolute;right:10px;top:8px;font-family:var(--hand);font-size:16px;color:#FFD966}
.ax-detail{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:22px;align-items:start}
.ax-sum{position:relative;padding:22px 24px 20px;background:#fff;border:1px solid #E1E5EE;box-shadow:0 22px 30px -28px rgba(13,24,56,.6)}
.ax-sum::before{content:"";position:absolute;left:18px;top:-8px;width:38px;height:14px;border-top:2px solid #9AA6C0;border-left:2px solid #9AA6C0;transform:rotate(-12deg)}
.ax-sum h3{margin:0;font-family:var(--hand);font-weight:700;font-size:28px;color:var(--ink);letter-spacing:0}
.ax-sum h3 small{font-size:19px;color:var(--soft);margin-left:8px}
.ax-sum .ax-sum-t{margin-top:12px;font-size:15.5px;line-height:1.7;color:var(--navy);max-height:420px;overflow:auto}
.ax-sum .ax-sum-t p{margin:0 0 10px!important}
.ax-sum-act{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:16px;padding-top:14px;border-top:1.5px dashed #DCE2EE}
.ax-modes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.ax-mode{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:14px 14px 12px;min-height:94px;background:#FFFEFB;border:1px solid #E1E5EE;border-radius:4px;cursor:pointer;font:inherit;text-align:left;box-shadow:0 12px 18px -18px rgba(13,24,56,.6);transition:transform .2s var(--ease),border-color .2s}
.ax-mode:hover{transform:translateY(-2px) rotate(-.4deg);border-color:var(--navy)}
.ax-mode:focus-visible{outline:2px solid var(--blue);outline-offset:2px}
.ax-mode:disabled{opacity:.45;cursor:not-allowed;transform:none}
.ax-mode b{font-size:15.5px;color:var(--navy)}
.ax-mode small{font-family:var(--hand);font-size:17px;color:var(--soft)}
.ax-mode .n{position:absolute;right:12px;top:10px;font-family:var(--disp);font-weight:800;font-size:24px;color:var(--blue)}
.ax-mode.big{grid-column:1 / -1;background:var(--navy);border-color:var(--navy);color:#fff;min-height:70px;flex-direction:row;align-items:center;gap:12px}
.ax-mode.big b{color:#fff;font-size:17px}.ax-mode.big small{color:#B4C0DA}.ax-mode.big .n{color:#FFD966;position:static;margin-left:auto}
.ax-leit{margin-top:16px}
.ax-leit h4{margin:0 0 8px;font-family:var(--hand);font-weight:700;font-size:24px;color:var(--ink);letter-spacing:0}
.ax-leit-box{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:4px;padding:8px;background:var(--navy);border-radius:4px}
.ax-leit-box div{display:flex;flex-direction:column;align-items:center;justify-content:space-between;gap:6px;min-height:118px;padding:6px 2px 8px;background:#F2F4F9;border-radius:2px;text-align:center}
.ax-leit-box small{font-family:var(--hand);font-size:15px;line-height:1;color:var(--ink)}
.ax-leit-box b{font-family:var(--hand);font-size:24px;color:var(--navy)}
.ax-leit-box i{display:block;width:70%;background:repeating-linear-gradient(#fff 0 3px,#C9D1E1 3px 4px);border-radius:1px}
.ax-leit p{margin-top:8px!important;font-family:var(--hand);font-size:18px;color:var(--soft)}
.ax-card-misc{display:flex;flex-direction:column;gap:18px;margin-top:22px}
#cards-view #global-review-widget:empty{display:none}
#cards-view #past-comparisons-section h3{font-family:var(--hand);font-size:26px;font-weight:700;color:var(--ink)}
@media (max-width: 1200px){.ax-detail{grid-template-columns:1fr}}
@media (max-width: 900px){.ax-lib{grid-template-columns:1fr}.ax-decks{position:static;max-height:none;flex-direction:row;overflow-x:auto;padding-bottom:12px}.ax-dbox{min-width:240px}#cards-view #cards-search{width:100%}}

