/* FAZ 3c: adım adım çöz (sonuç kâğıdı) */
:is(#exams-view.axs,#axs-layer) .sn-prac [data-steps-open]{margin-left:14px}
:is(#exams-view.axs,#axs-layer) .sn-steps-b{margin-top:6px;padding:10px 12px;border:1.4px solid #DCE2EE;border-radius:6px;background:#FBFCFE}
:is(#exams-view.axs,#axs-layer) .sn-steps-b[hidden]{display:none}
:is(#exams-view.axs,#axs-layer) .sn-steps-q{margin:0 0 8px;font-size:14.5px;line-height:1.5;color:var(--ink)}
:is(#exams-view.axs,#axs-layer) .sn-steps-in{display:block;width:100%;box-sizing:border-box;min-height:120px;padding:8px 10px;border:1.4px solid #C9D1E1;border-radius:6px;background:#fff;color:var(--navy);font-family:'JetBrains Mono',ui-monospace,monospace;font-size:14.5px;line-height:1.6;resize:vertical}
