:is(#exams-view.axs,#axs-layer) .sn-steps-sum{margin:10px 0 0;font-size:14px;font-weight:600}
:is(#exams-view.axs,#axs-layer) .sn-steps-sum[hidden]{display:none}
:is(#exams-view.axs,#axs-layer) .sn-steps-sum.ok{color:var(--green)}
:is(#exams-view.axs,#axs-layer) .sn-steps-sum.half{color:var(--amber)}
:is(#exams-view.axs,#axs-layer) .sn-steps-sum.no{color:var(--red)}
/* FAZ 4b: grafik çizme (exam-engine 'graph' tipi) */
.axg{display:grid;gap:8px;max-width:680px}
.axg-tools{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.axg-tools button,.axg-type button{min-height:38px;padding:0 12px;border:1.4px solid #C9D1E1;border-radius:6px;background:#F7F9FD;color:#1A2A5C;font:inherit;font-size:14px;cursor:pointer}
.axg-tools button[aria-pressed="true"]{background:#0D1838;border-color:#0D1838;color:#fff}
.axg-tools button:disabled{opacity:.45;cursor:default}
.axg-tools button:focus-visible,.axg-type button:focus-visible,.axg-mini:focus-visible,.axg-pick:focus-visible{outline:2px solid #2F6BFF;outline-offset:1px}
.axg-sp{flex:1 1 8px}
