.axg-stage{border:1.4px solid #DCE2EE;border-radius:8px;background:#fff;padding:4px}
.axg-svg{display:block;width:100%;height:auto;max-height:min(520px,68vh);margin:0 auto;touch-action:none;user-select:none;-webkit-user-select:none;font-family:'Instrument Sans',system-ui,sans-serif;cursor:crosshair}
.axg-svg.st{cursor:default;touch-action:auto}
