.axg-svg .axg-frame{fill:none;stroke:#C9D1E1;stroke-width:1.2}
.axg-svg .axg-tk{font-size:11.5px;fill:#4B5675}
.axg-svg .axg-at{font-size:12.5px;font-weight:600;fill:#1A2A5C}
.axg-svg .axg-ln{fill:none;stroke-width:2.6;stroke-linecap:round}
.axg-svg .axg-pt{stroke:#fff;stroke-width:1.6}
.axg-svg .axg-ar{stroke-width:1.6}
.axg-svg .axg-lb{font-size:13px;font-weight:700;paint-order:stroke;stroke:#fff;stroke-width:3px}
.axg-svg .axg-seed{stroke:none}
.axg-svg .axg-gv.axg-ln{stroke:#8A91A8}.axg-svg .axg-gv.axg-pt,.axg-svg .axg-gv.axg-lb{fill:#6A7593}.axg-svg .axg-gv.axg-ar{fill:rgba(138,145,168,.18);stroke:#8A91A8}
.axg-svg .axg-st.axg-ln{stroke:#2F6BFF}.axg-svg .axg-st.axg-pt,.axg-svg .axg-st.axg-lb,.axg-svg .axg-st.axg-seed{fill:#2F6BFF}.axg-svg .axg-st.axg-ar{fill:rgba(47,107,255,.18);stroke:#2F6BFF}
.axg-svg .axg-st.sel.axg-ln{stroke:#B4511F}.axg-svg .axg-st.sel.axg-pt{fill:#B4511F}.axg-svg .axg-st.sel.axg-ar{stroke:#B4511F}
.axg-svg .axg-ok.axg-ln{stroke:#1E8A55;stroke-dasharray:8 5}.axg-svg .axg-ok.axg-pt,.axg-svg .axg-ok.axg-lb{fill:#1E8A55}.axg-svg .axg-ok.axg-ar{fill:rgba(30,138,85,.14);stroke:#1E8A55;stroke-dasharray:6 4}
.axg-svg .axg-hd{fill:#fff;stroke:#2F6BFF;stroke-width:2;cursor:grab}
.axg-svg .axg-hd.on{fill:#B4511F;stroke:#fff}
.axg-svg .axg-pd{fill:none;stroke:#B4511F;stroke-width:2.4;stroke-dasharray:3 3}
.axg-svg .axg-cur line{stroke:#B4511F;stroke-width:1.6}
.axg-svg:not(:focus) .axg-cur{display:none}
.axg-bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;min-height:24px}
.axg-coord{font-family:'JetBrains Mono',ui-monospace,monospace;font-size:13px;color:#1A2A5C}
.axg-type{display:flex;flex-wrap:wrap;gap:6px;align-items:flex-end}
.axg-type label{display:grid;gap:3px;flex:1 1 240px;font-size:12.5px;font-weight:600;color:#1A2A5C}
.axg-type-in{min-height:42px;padding:6px 10px;border:1.6px solid #C9D1E1;border-radius:8px;font-family:'JetBrains Mono',ui-monospace,monospace;font-size:15px;color:#0D1838;background:#fff;box-sizing:border-box;width:100%}
