.axg-type-msg{flex:1 1 100%;font-size:12.5px;color:#6A7593}
.axg-type-msg.ok{color:#1E8A55}.axg-type-msg.bad{color:#C9483B}
.axg-list{margin:0;padding:0;list-style:none;display:grid;gap:6px}
.axg-list[hidden]{display:none}
.axg-list li{display:grid;grid-template-columns:auto 1fr;gap:4px 8px;align-items:center;padding:7px 9px;border:1.3px solid #DCE2EE;border-radius:8px;background:#FBFCFE}
.axg-list li.sel{border-color:#B4511F;background:#FFF8F2}
