.axg-row select{min-height:32px;border:1.3px solid #C9D1E1;border-radius:6px;font:inherit;font-size:13px;padding:0 6px;background:#fff}
.axg-mini{min-height:32px;padding:0 10px;border:1.3px solid #C9D1E1;border-radius:6px;background:#fff;color:#1A2A5C;font:inherit;font-size:13px;cursor:pointer}
