.axg-none{display:flex;gap:8px;align-items:center;font-size:13.5px;color:#4B5675;min-height:32px}
.axg-none input{width:18px;height:18px}
.axg-keys{margin:0;font-size:12px;color:#6A7593}
.axg-err{color:#C9483B}
.axg .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.axg-res{margin:10px 0;max-width:640px}
.axg-res figcaption{display:flex;flex-wrap:wrap;gap:12px;margin:6px 0 0;font-size:12.5px;color:#4B5675}
