.axg-els li.ok::before{content:"✓";color:#1E8A55}.axg-els li.half::before{content:"½";color:#B4511F}.axg-els li.no::before{content:"✗";color:#C9483B}
@media (max-width:560px){.axg-tools button{padding:0 9px;font-size:13px;min-height:40px}.axg-xy input{width:50px}}
