/* eski "Odak modu" Pomodoro düğmesi kaldırıldı: Pomodoro artık yalnızca Study Lab’de */
#pomodoro-widget-container,#pomodoro-dim-overlay{display:none!important}

/* ===== Özet kartı + matbaa ===== */

/* ---------- kabuk ---------- */
#study-card-modal.axr{--pp:#FFFDF8;--line:#E4E0D4;--ink:#1A2A5C;--navy:#0D1838;--blue:#2F6BFF;--muted:#4B5675;--soft:#6A7593;--red:#C9483B;--green:#1E8A55;--amber:#B4511F;--hand:'Caveat','Segoe Print',cursive;--disp:'Bricolage Grotesque',system-ui,sans-serif;--mono:'JetBrains Mono',ui-monospace,monospace;--ease:cubic-bezier(.2,.7,.2,1);
  padding:0!important;background:rgba(13,24,56,.55)!important;backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);align-items:stretch!important;justify-content:center!important}
#study-card-modal.axr .axr-defs{position:absolute;width:0;height:0;overflow:hidden}
#study-card-modal.axr .axr-card{position:relative;display:flex;flex-direction:column;width:min(1240px,calc(100vw - 28px))!important;max-width:none!important;height:calc(100vh - 28px)!important;max-height:none!important;margin:14px auto!important;padding:0!important;border-radius:14px!important;border:1px solid #D9D3C3!important;background:var(--pp)!important;background-image:var(--grain)!important;background-size:220px!important;box-shadow:0 40px 80px -30px rgba(13,24,56,.6)!important;overflow:hidden!important;transform:none!important;color:var(--navy);font-family:'Instrument Sans',system-ui,sans-serif}
#study-card-modal.axr.active .axr-card{animation:axrIn .45s var(--ease) both}
@keyframes axrIn{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}
#study-card-modal.axr .axr-card.split-active{width:calc(100vw - 28px)!important}
#study-card-modal.axr .axr-card,#study-card-modal.axr .axr-story{text-align:left}
#study-card-modal.axr .axr-sprev:focus-visible,#study-card-modal.axr .axr-snext:focus-visible{outline:0}
body.axr-open #pomodoro-widget-container,body.axr-open #acadia-widget-container,body.axr-open .acadia-fab-wrap,body.axr-open #btn-acadia-toggle,body.axr-open .ax-fab{display:none!important}
#study-card-modal.axr .hand{font-family:var(--hand);font-weight:600}
#study-card-modal.axr .mono{font-family:var(--mono)}
#study-card-modal.axr .disp{font-family:var(--disp)}
#study-card-modal.axr .vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
#study-card-modal.axr [hidden]{display:none!important}
#study-card-modal.axr button{font:inherit;color:inherit}
#study-card-modal.axr :focus-visible{outline:2px solid var(--blue);outline-offset:2px}

/* üst bar */
#study-card-modal.axr .axr-top{position:relative;flex:none;display:flex!important;align-items:center;gap:14px;padding:12px 18px 12px 24px!important;margin:0!important;border:0!important;border-bottom:1px solid var(--line)!important;background:rgba(255,253,248,.92)!important}
#study-card-modal.axr .axr-top-l{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
#study-card-modal.axr .axr-eyb{font-size:10.5px;letter-spacing:.16em;color:var(--soft)}
#study-card-modal.axr #study-card-title{margin:0;font-family:var(--disp)!important;font-size:19px!important;font-weight:700;color:var(--navy)!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#study-card-modal.axr .axr-top-r{display:flex;align-items:center;gap:6px;flex-wrap:nowrap}
#study-card-modal.axr .axr-vote{display:flex!important;align-items:center;gap:2px;margin:0 6px 0 0!important;padding:0!important;background:none!important;border:0!important}
#study-card-modal.axr .axr-vote .hand{font-size:17px;color:var(--soft);margin-right:4px}
#study-card-modal.axr .vote-btn{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:9px;border:1px solid transparent!important;background:none!important;cursor:pointer;color:var(--muted);padding:0!important}
#study-card-modal.axr .vote-btn svg,#study-card-modal.axr .axr-tb svg,#study-card-modal.axr .axr-x svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
#study-card-modal.axr .vote-btn:hover{background:#F1EEE4!important}
#study-card-modal.axr .vote-btn.active,#study-card-modal.axr .vote-btn.voted,#study-card-modal.axr .vote-btn[aria-pressed="true"]{color:var(--blue);border-color:#BFD0FF!important;background:#EEF3FF!important}
#study-card-modal.axr .vote-btn.active svg path:first-child{fill:currentColor}
#study-card-modal.axr .axr-tb{display:inline-flex!important;align-items:center;gap:6px;height:38px;min-width:38px;padding:0 11px!important;border-radius:9px!important;border:1px solid #DCD6C6!important;background:#fff!important;color:var(--ink)!important;font-size:13.5px!important;font-weight:600!important;cursor:pointer;white-space:nowrap;box-shadow:none!important;margin:0!important;transform:none!important}
#study-card-modal.axr .axr-tb:hover{border-color:var(--ink)!important}
#study-card-modal.axr .axr-tb b{font-family:var(--disp);font-size:16px}
#study-card-modal.axr .axr-tb[aria-expanded="true"]{background:var(--navy)!important;color:#fff!important;border-color:var(--navy)!important}
#study-card-modal.axr .axr-x{display:inline-flex!important;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%!important;border:0!important;background:var(--navy)!important;color:#fff!important;cursor:pointer;margin-left:4px!important;position:static!important;padding:0!important}
#study-card-modal.axr .axr-x:hover{transform:rotate(90deg);transition:transform .25s var(--ease)}
#study-card-modal.axr .axr-prog{position:absolute;left:0;right:0;bottom:-1px;height:3px;background:transparent}
#study-card-modal.axr .axr-prog i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--blue),#7FA2FF);border-radius:0 3px 3px 0;transition:width .15s linear}
#study-card-modal.axr .axr-styles{flex:none}
#study-card-modal.axr .axr-styles:empty{display:none}
#study-card-modal.axr .axr-styles:not(:empty){padding:8px 24px;border-bottom:1px dashed var(--line);display:flex;gap:6px;flex-wrap:wrap;align-items:center;font-size:13px}
#study-card-modal.axr .axr-styles button,#study-card-modal.axr .axr-styles a{border-radius:999px!important;font-size:12.5px!important}

/* bölünmüş görünüm */
#study-card-modal.axr .axr-split{flex:1;min-height:0;height:auto!important;display:flex;gap:0!important}
#study-card-modal.axr .axr-body{flex:1;min-width:0;width:100%;box-sizing:border-box;height:100%;overflow-y:auto!important;overflow-x:hidden;padding:0!important;scroll-behavior:auto;overscroll-behavior:contain}
#study-card-modal.axr .axr-orig{flex:1;min-width:0;height:100%;border-left:1px solid var(--line);background:#F3F1EA;padding:8px;overflow:hidden}
#study-card-modal.axr .axr-legacy{display:none!important}

/* ---------- dergi düzeni ---------- */
#study-card-modal.axr .axr-mag{box-sizing:border-box;width:100%;display:grid;grid-template-columns:210px minmax(0,1fr);gap:0 40px;max-width:1120px;margin:0 auto;padding:30px 36px 120px}
#study-card-modal.axr .split-active .axr-mag{grid-template-columns:minmax(0,1fr);padding:22px 22px 100px}
#study-card-modal.axr .split-active .axr-rail{display:none}
#study-card-modal.axr .axr-rail{position:sticky;top:20px;align-self:start;max-height:calc(100vh - 140px);overflow:auto;padding-top:8px}
#study-card-modal.axr .axr-rk{display:block;font-size:10.5px;letter-spacing:.16em;color:var(--soft);margin:0 0 12px 2px}
#study-card-modal.axr .axr-rail ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px;border-left:1.5px solid var(--line)}
#study-card-modal.axr .axr-rail a{position:relative;display:block;padding:7px 10px 7px 16px;margin-left:-1.5px;border-left:1.5px solid transparent;text-decoration:none;color:var(--soft);font-size:13.5px;line-height:1.3;border-radius:0 6px 6px 0;transition:color .2s,background .2s}
#study-card-modal.axr .axr-rail a i{position:absolute;left:-1.5px;top:0;width:3px;height:calc(var(--p) * 100%);background:var(--blue);border-radius:2px;transition:height .15s linear}
#study-card-modal.axr .axr-rail a:hover{color:var(--navy);background:#F3F0E6}
#study-card-modal.axr .axr-rail a.cur{color:var(--navy);font-weight:700}
#study-card-modal.axr .axr-rail a.done span::after{content:' ✓';color:var(--green);font-weight:700}
#study-card-modal.axr .axr-main{--fs:16.5px;--lh:1.75;min-width:0;max-width:700px}
#study-card-modal.axr .axr-main[data-font="serif"] .axr-prose,#study-card-modal.axr .axr-main[data-font="serif"] .axr-kps{font-family:Georgia,'Iowan Old Style','Times New Roman',serif}
#study-card-modal.axr .axr-main[data-font="dys"] .axr-prose,#study-card-modal.axr .axr-main[data-font="dys"] .axr-kps,#study-card-modal.axr .axr-main[data-font="dys"] .axr-pull blockquote{font-family:Verdana,'Atkinson Hyperlegible',Tahoma,sans-serif;letter-spacing:.035em;word-spacing:.12em}

/* başlık */
#study-card-modal.axr .axr-mastin{padding:6px 0 22px;border-bottom:2px solid var(--navy);margin-bottom:18px}
#study-card-modal.axr .axr-kicker{font-size:22px;color:var(--blue)}
#study-card-modal.axr .axr-h1{margin:4px 0 14px;font-size:clamp(30px,4.2vw,50px);line-height:1.04;letter-spacing:-.02em;font-weight:800;color:var(--navy)}
#study-card-modal.axr .axr-h1 span{background:linear-gradient(transparent 62%,#FFE58A 62%,#FFE58A 90%,transparent 90%) no-repeat;background-size:0 100%;animation:axrMark 1s .35s var(--ease) forwards}
@keyframes axrMark{to{background-size:100% 100%}}
#study-card-modal.axr .axr-chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}
#study-card-modal.axr .axr-chip{font-size:12px;font-weight:600;padding:3px 10px;border-radius:999px;border:1px solid #D9D3C3;background:#fff;color:var(--muted)}
#study-card-modal.axr .axr-chip.ok{border-color:#B7DEC8;color:var(--green);background:#EFF8F2}
#study-card-modal.axr .axr-chip.q{border-color:#F0D7A8;color:var(--amber);background:#FFF7E6}
/* UYARI rozeti (24.10.2026): eksik pencere, kismi Gemini taslagi, atlanan
   asama, dusuk sayisal kapsama. Oncesinde bu bilgiler yalnizca gizli
   .axr-legacy DOM'una yaziliyordu, yani %23 kapsamali bir kart tam kartla
   birebir ayni gorunuyordu — ustelik yaninda yesil "kalite kontrolunden
   gecti" rozetiyle. Kirmizi degil kehribar/kiremit: kart KULLANILABILIR,
   yalnizca eksik. */
#study-card-modal.axr .axr-chip.warn{border-color:#E8B4A0;color:#B4541F;background:#FDF1EC}
#study-card-modal.axr .axr-meta{display:flex;flex-wrap:wrap;gap:6px 16px;margin:0;font-size:12px;color:var(--soft);letter-spacing:.04em}
#study-card-modal.axr .axr-meta span+span::before{content:'·';margin-right:16px;color:#C9C2B0}
#study-card-modal.axr .axr-meta [data-left]{color:var(--blue);font-weight:700}
#study-card-modal.axr .axr-meta [data-left]:empty{display:none}

/* paylaş */
#study-card-modal.axr .axr-share{display:flex!important;align-items:center;justify-content:space-between;gap:14px;margin:0 0 26px!important;padding:10px 14px!important;border:1px dashed #CFC8B6!important;border-radius:10px!important;background:#FBF9F2!important;font-size:14px;font-weight:600;color:var(--ink)}
#study-card-modal.axr .axr-share small{display:block;font-weight:400;color:var(--soft);font-size:12.5px}
#study-card-modal.axr .axr-share[style*="display: none"]{display:none!important}

/* bölüm iskeleti */
#study-card-modal.axr .axr-ch{scroll-margin-top:20px;margin:0 0 46px}
#study-card-modal.axr .axr-lbl{display:inline-block;font-size:10.5px;letter-spacing:.18em;color:var(--red);border:1.4px solid var(--red);border-radius:3px;padding:1px 6px;transform:rotate(-1.5deg)}
#study-card-modal.axr .axr-sech{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 14px;margin-bottom:16px}
#study-card-modal.axr .axr-sech h2{flex:1 1 100%;order:2;margin:2px 0 0;font-size:clamp(23px,2.6vw,30px);line-height:1.15;font-weight:800;letter-spacing:-.01em;color:var(--navy)}
#study-card-modal.axr .axr-sech .axr-mini{order:1;margin-left:auto}
#study-card-modal.axr .axr-h3{font-size:24px;color:var(--ink);margin:26px 0 8px}
#study-card-modal.axr .axr-mini{display:inline-flex;align-items:center;gap:5px;min-height:34px;padding:0 11px;border-radius:999px;border:1px solid #D4CDBB;background:#fff;font-size:12.5px!important;font-weight:600;color:var(--ink)!important;cursor:pointer;transition:border-color .15s,background .15s}
#study-card-modal.axr .axr-mini svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#study-card-modal.axr .axr-mini:hover{border-color:var(--ink)}
#study-card-modal.axr .axr-mini.on{background:var(--navy);border-color:var(--navy);color:#fff!important}
#study-card-modal.axr .axr-mini:disabled{opacity:.55;cursor:default}
#study-card-modal.axr .axr-mini.busy svg{animation:axrSpin 1s linear infinite}
@keyframes axrSpin{to{transform:rotate(360deg)}}

/* metin */
#study-card-modal.axr .axr-prose{font-size:var(--fs);line-height:var(--lh);color:#1E2747}
#study-card-modal.axr .axr-prose p{margin:0 0 1em}
#study-card-modal.axr .axr-prose h4{font-family:var(--disp);font-size:1.15em;margin:1.4em 0 .5em;color:var(--navy)}
#study-card-modal.axr .axr-prose ul,#study-card-modal.axr .axr-prose ol{margin:0 0 1em;padding-left:1.3em}
#study-card-modal.axr .axr-prose li{margin:.3em 0}
#study-card-modal.axr .axr-prose strong,#study-card-modal.axr .axr-prose b{color:var(--navy)}
#study-card-modal.axr .axr-prose sup a,#study-card-modal.axr .axr-prose .footnote-ref{color:var(--blue);font-family:var(--mono);font-size:.7em;text-decoration:none}
#study-card-modal.axr .dropcap>p:first-of-type::first-letter{float:left;font-family:var(--disp);font-weight:800;font-size:3.6em;line-height:.82;margin:.06em .1em 0 0;color:var(--blue)}
#study-card-modal.axr .axr-main.focus [data-b]{transition:opacity .3s,filter .3s;opacity:.32;filter:blur(.4px)}
#study-card-modal.axr .axr-main.focus [data-b].now,#study-card-modal.axr .axr-main.focus [data-b]:hover{opacity:1;filter:none}

/* 30 saniye */
#study-card-modal.axr .axr-pull{position:relative;padding:22px 26px 20px;border-radius:14px;background:var(--navy);color:#EEF2FF;box-shadow:0 18px 34px -24px rgba(13,24,56,.8);transform:translateY(12px);opacity:0;transition:transform .6s var(--ease),opacity .6s}
#study-card-modal.axr .axr-pull.in{transform:none;opacity:1}
#study-card-modal.axr .axr-pull .axr-lbl{color:#FFD86B;border-color:#FFD86B}
#study-card-modal.axr .axr-pull blockquote{margin:12px 0 0;font-family:var(--disp);font-size:clamp(18px,2vw,22px);line-height:1.45;font-weight:500}
#study-card-modal.axr .axr-pull blockquote p{margin:0 0 .5em}
#study-card-modal.axr .axr-pull blockquote ul{margin:.3em 0;padding-left:1.2em}
#study-card-modal.axr .axr-pull strong{color:#fff;background:linear-gradient(transparent 60%,rgba(47,107,255,.6) 60%)}
#study-card-modal.axr .axr-nums{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:14px}
#study-card-modal.axr .axr-num{padding:14px 16px;border-radius:12px;border:1.5px solid var(--c);background:#fff;box-shadow:3px 3px 0 var(--c)}
#study-card-modal.axr .axr-num b{display:block;font-size:clamp(28px,3.4vw,40px);line-height:1.05;font-weight:800;color:var(--c);font-variant-numeric:tabular-nums}
#study-card-modal.axr .axr-num span{display:block;margin-top:4px;font-size:13px;line-height:1.35;color:var(--muted)}

/* bölüm kâğıtları */
#study-card-modal.axr .axr-sheet{position:relative;padding:30px 32px 26px;background:#fff;border:1px solid #E3DECF;border-radius:4px;box-shadow:0 1px 0 #EDE8DA,0 18px 30px -26px rgba(13,24,56,.55);transform:rotate(var(--r)) translateY(16px);opacity:0;transition:transform .7s var(--ease),opacity .7s}
#study-card-modal.axr .axr-sheet.in{transform:rotate(var(--r));opacity:1}
#study-card-modal.axr .axr-sheet::before{content:'';position:absolute;top:-9px;left:50%;width:84px;height:20px;margin-left:-42px;background:rgba(255,229,138,.75);transform:rotate(-2deg);box-shadow:0 1px 2px rgba(0,0,0,.08)}
#study-card-modal.axr .axr-secn{position:absolute;top:10px;right:18px;font-size:54px;font-weight:800;line-height:1;color:#EEF2FB;letter-spacing:-.04em;pointer-events:none}
#study-card-modal.axr .axr-sheet h2{position:relative;margin:0 0 14px;font-size:clamp(21px,2.3vw,27px);line-height:1.2;font-weight:800;color:var(--navy);padding-right:60px}
#study-card-modal.axr .axr-kps{list-style:none;margin:16px 0 0;padding:14px 0 0;border-top:1px dashed #DDD6C3;font-size:calc(var(--fs) * .94);line-height:1.6}
#study-card-modal.axr .axr-kps li{position:relative;padding-left:28px;margin:.45em 0}
/* "Diagram/Visual:" oneki yerine etiket (25.10.2026) — bkz. gorselKp (acadex-ink.js). */
#study-card-modal.axr .axr-kptag{display:inline-block;font-size:10px;letter-spacing:.12em;color:var(--blue);border:1.2px solid currentColor;border-radius:3px;padding:0 5px;margin-right:2px;vertical-align:.12em;text-transform:uppercase}
#study-card-modal.axr .axr-kps li::before{content:'';position:absolute;left:3px;top:.38em;width:13px;height:13px;border:1.6px solid var(--blue);border-radius:3px;transform:rotate(-4deg)}
#study-card-modal.axr .axr-kps li::after{content:'';position:absolute;left:6px;top:.5em;width:10px;height:5px;border-left:2px solid var(--blue);border-bottom:2px solid var(--blue);transform:rotate(-48deg) scale(0);transform-origin:left bottom;transition:transform .3s var(--ease)}
#study-card-modal.axr .in .axr-kps li::after,#study-card-modal.axr .axr-kps.big li::after{transform:rotate(-48deg) scale(1)}
#study-card-modal.axr .axr-kps.big{border-top:0;padding-top:0;font-size:var(--fs)}
#study-card-modal.axr .axr-secvis{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:18px;padding-top:12px;border-top:1px dotted #DDD6C3}
#study-card-modal.axr .axr-secvis .hand{font-size:18px;color:var(--soft);margin-right:4px}

/* ---------- şekiller ---------- */
#study-card-modal.axr .axr-fig{position:relative;margin:0 0 22px;padding:16px 18px 14px;background:#fff;border:1px solid #E3DECF;border-radius:12px}
#study-card-modal.axr .axr-fig figcaption{display:flex;flex-direction:column;gap:2px;margin-bottom:10px}
#study-card-modal.axr .axr-fig figcaption .mono{font-size:10px;letter-spacing:.16em;color:var(--soft)}
#study-card-modal.axr .axr-fig figcaption b{font-family:var(--disp);font-size:17px;color:var(--navy)}
#study-card-modal.axr .axr-figp{margin:8px 0 0;font-size:13.5px;line-height:1.5;color:var(--muted)}
#study-card-modal.axr .axr-grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(330px,100%),1fr));gap:16px}
#study-card-modal.axr .axr-grid2>.axr-fig{margin:0}
/* Tek sutuna sigmayan formul tum genislige yayilir (bkz.
   sigdirFormulKutusu): .axr-tex'teki overflow-x kaydirma cubugu birakiyor
   ve formulun sagi hem ekranda hem ciktida kayboluyor. */
#study-card-modal.axr .axr-grid2>.axr-fig.formula-card-wide{grid-column:1/-1}
#study-card-modal.axr .axr-grid2+*{margin-top:22px}
#study-card-modal.axr .axr-chartw{position:relative}
#study-card-modal.axr .axr-chartw [data-redraw]{position:absolute;top:12px;right:12px;min-height:30px;opacity:0;transition:opacity .2s}
#study-card-modal.axr .axr-chartw:hover [data-redraw],#study-card-modal.axr .axr-chartw [data-redraw]:focus-visible{opacity:1}
.axr-chart{display:block;width:100%;height:auto;overflow:visible}
.axr-chart text{font-family:'Instrument Sans',system-ui,sans-serif;font-size:16px;fill:#4B5675}
.axr-chart text.hand{font-family:'Caveat',cursive;font-weight:700;font-size:24px;fill:#0D1838}
.axr-chart text.mono{font-family:'JetBrains Mono',monospace;font-size:13px;fill:#8A93AB}
.axr-chart .grid path{fill:none;stroke:#ECE7DA;stroke-width:1;stroke-dasharray:3 5}
.axr-chart .grid text{text-anchor:end}
.axr-chart .axis{fill:none;stroke:#1A2A5C;stroke-width:2;stroke-linecap:round}
.axr-chart .xl text{text-anchor:middle;font-size:15px}
.axr-chart .bar .b{stroke-width:2;stroke-linejoin:round;transform-box:fill-box;transform-origin:bottom;transform:scaleY(0)}
.axr-chart .bar .v{text-anchor:middle;opacity:0}
.axr-chart .bar:hover .b{filter:brightness(.95)}
.in>.axr-chart .bar .b,.in .axr-chart .bar .b{animation:axrGrow .8s var(--d) cubic-bezier(.3,1.4,.5,1) forwards}
.in>.axr-chart .bar .v,.in .axr-chart .bar .v{animation:axrFade .4s calc(var(--d) + .55s) forwards}
@keyframes axrGrow{to{transform:scaleY(1)}}
@keyframes axrFade{to{opacity:1}}
.axr-chart .ln{fill:none;stroke:#2F6BFF;stroke-width:3.2;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1}
.axr-chart .area{fill:rgba(47,107,255,.09);opacity:0}
.axr-chart .pt{opacity:0}
.axr-chart .pt circle{fill:#fff;stroke:#2F6BFF;stroke-width:2.6}
.axr-chart .pt .v{text-anchor:middle}
.axr-chart .pt:hover circle{fill:#2F6BFF}
.in .axr-chart .ln{animation:axrDraw 1.3s .1s var(--ease,ease) forwards}
.in .axr-chart .area{animation:axrFade .8s 1s forwards}
.in .axr-chart .pt{animation:axrPop .4s var(--d) cubic-bezier(.3,1.6,.5,1) forwards}
@keyframes axrDraw{to{stroke-dashoffset:0}}
@keyframes axrPop{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.axr-chart .arc{fill:none;stroke:var(--c);stroke-dasharray:0 100;stroke-dashoffset:var(--o);opacity:.92;transition:opacity .2s}
.in .axr-chart .arc{animation:axrArc .9s var(--d) var(--ease,ease) forwards}
@keyframes axrArc{to{stroke-dasharray:var(--p) 100}}
.axr-chart .arc:hover{opacity:1;stroke-width:+4}
.axr-chart .rim{fill:none;stroke:#1A2A5C;stroke-width:1.6;opacity:.5}
.axr-chart .ctr{text-anchor:middle;font-size:26px;font-weight:800;fill:#0D1838;font-family:'Bricolage Grotesque',sans-serif}
.axr-chart .leg .li{opacity:0}
.in .axr-chart .leg .li{animation:axrPop .4s var(--d) forwards}
.axr-chart .leg .v{text-anchor:end}
#study-card-modal.axr .axr-tip{position:absolute;z-index:3;pointer-events:none;padding:4px 10px;border-radius:8px;background:var(--navy);color:#fff;font-size:18px;white-space:nowrap;box-shadow:0 8px 16px -8px rgba(0,0,0,.5)}

/* diyagram */
#study-card-modal.axr .axr-dgbox{overflow-x:auto;padding:6px 0;text-align:center;min-height:80px}
#study-card-modal.axr .axr-wait{color:var(--soft);font-size:19px}
#study-card-modal.axr .axr-inked .node rect,#study-card-modal.axr .axr-inked .node polygon,#study-card-modal.axr .axr-inked .node circle,#study-card-modal.axr .axr-inked .node path{fill:#fff!important;stroke:#1A2A5C!important;stroke-width:1.8px!important;filter:url(#axr-rough)}
#study-card-modal.axr .axr-inked .node .nodeLabel,#study-card-modal.axr .axr-inked .node text{color:#0D1838!important;fill:#0D1838!important}
#study-card-modal.axr .axr-inked .edgePath path,#study-card-modal.axr .axr-inked .flowchart-link{stroke:#2F6BFF!important;stroke-width:2px!important}
#study-card-modal.axr .axr-inked .edgeLabel,#study-card-modal.axr .axr-inked .edgeLabel *{background:#FFFDF8!important;color:#4B5675!important}
#study-card-modal.axr .axr-inked marker path{fill:#2F6BFF!important;stroke:#2F6BFF!important}
#study-card-modal.axr .axr-inked g.node{cursor:pointer;opacity:0;transition:opacity .35s,transform .35s}
#study-card-modal.axr .axr-inked .flowchart-link,#study-card-modal.axr .axr-inked .edgePath path{stroke-dasharray:1;stroke-dashoffset:1}
#study-card-modal.axr .axr-dg.in .axr-inked g.node{animation:axrFade .45s calc(var(--i) * .16s) forwards}
#study-card-modal.axr .axr-dg.in .axr-inked .flowchart-link,#study-card-modal.axr .axr-dg.in .axr-inked .edgePath path{animation:axrDraw .6s calc(var(--i) * .16s + .3s) forwards}
#study-card-modal.axr .axr-dg.stepping .axr-inked g.node,#study-card-modal.axr .axr-dg.stepping .axr-inked .flowchart-link,#study-card-modal.axr .axr-dg.stepping .axr-inked .edgePath path{animation:none;opacity:1;stroke-dashoffset:0}
#study-card-modal.axr .axr-dg.stepping .axr-inked .off{opacity:.08!important}
#study-card-modal.axr .axr-dg.stepping .axr-inked g.node.cur rect,#study-card-modal.axr .axr-dg.stepping .axr-inked g.node.cur polygon,#study-card-modal.axr .axr-dg.stepping .axr-inked g.node.cur circle{fill:#FFF3C4!important;stroke:#B4511F!important;stroke-width:2.4px!important}
#study-card-modal.axr .axr-dgbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:8px}
#study-card-modal.axr .axr-dgnav{display:inline-flex;align-items:center;gap:6px}
#study-card-modal.axr .axr-dgnav .mono{font-size:12px;color:var(--soft);min-width:42px;text-align:center}
#study-card-modal.axr .axr-dgcap{font-size:20px;color:var(--ink)}

/* tablo */
#study-card-modal.axr .axr-tscroll{overflow-x:auto;margin:0 -4px}
#study-card-modal.axr .axr-tbl table{width:100%;border-collapse:collapse;font-size:14px}
#study-card-modal.axr .axr-tbl th{text-align:left;border-bottom:2px solid var(--navy);padding:0;white-space:nowrap}
#study-card-modal.axr .axr-tbl th button{display:inline-flex;align-items:center;gap:6px;min-height:40px;padding:6px 10px;border:0;background:none;font-weight:700;color:var(--navy);cursor:pointer}
#study-card-modal.axr .axr-tbl th button i::after{content:'↕';font-style:normal;color:#B9C0D3;font-size:12px}
#study-card-modal.axr .axr-tbl th[aria-sort="ascending"] button i::after{content:'↑';color:var(--blue)}
#study-card-modal.axr .axr-tbl th[aria-sort="descending"] button i::after{content:'↓';color:var(--blue)}
#study-card-modal.axr .axr-tbl .axr-colc{min-height:30px!important;padding:4px 6px!important;color:var(--blue)!important}
#study-card-modal.axr .axr-tbl .axr-colc svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}
#study-card-modal.axr .axr-tbl td{padding:9px 10px;border-bottom:1px solid #EEE9DC;vertical-align:top;line-height:1.45}
#study-card-modal.axr .axr-tbl td.n{font-family:var(--mono);font-size:13px;text-align:right}
#study-card-modal.axr .axr-tbl tbody tr{cursor:pointer;transition:background .2s}
#study-card-modal.axr .axr-tbl tbody tr:hover{background:#F7F4EA}
#study-card-modal.axr .axr-tbl tbody tr.mark{background:#FFF3C4;box-shadow:inset 3px 0 0 #C88A1C}
#study-card-modal.axr .axr-tbl tbody tr.slide{animation:axrRow .4s calc(var(--i) * .04s) var(--ease) both}
@keyframes axrRow{from{opacity:0;transform:translateX(-10px)}to{opacity:1;transform:none}}
#study-card-modal.axr .axr-tbl.in tbody tr{animation:axrRow .45s calc(var(--r0,0) * 1s) var(--ease) both}
#study-card-modal.axr .axr-colchart:not(:empty){margin-top:12px;padding-top:10px;border-top:1px dashed #DDD6C3}

/* formül stüdyosu (kara tahta) */
#study-card-modal.axr .axr-studio{margin-top:22px}
#study-card-modal.axr .axr-studio>h3{font-size:24px;color:var(--ink);margin:0 0 10px}
#study-card-modal.axr .axr-chalk{background:#1F3A33;background-image:radial-gradient(rgba(255,255,255,.05) 1px,transparent 1px);background-size:6px 6px;border:8px solid #8A5A35;border-radius:8px;color:#F2F0E6;box-shadow:inset 0 0 40px rgba(0,0,0,.35)}
#study-card-modal.axr .axr-chalk figcaption .mono{color:#B9D4C6}
#study-card-modal.axr .axr-chalk figcaption b{color:#FFF}
/* SATIR ICI MATEMATIK: anlati ve maddelerde cevresindeki metinden ayirt
   edilsin. Koyu temada cok sonuk kaliyordu. */
#study-card-modal.axr .axr-prose .katex,
#study-card-modal.axr .axr-kps .katex{color:var(--amber)}
/* Gece masasi kok ogeyi ters ceviriyor ve .katex'i GERI ceviriyor; satir
   ici matematik boylece cevresindeki metnin tersine donup koyu kaliyordu.
   Burada geri cevirme iptal: metinle ayni mantikta cevrilsin. */
html.ax-dark #study-card-modal.axr .axr-prose .katex,
html.ax-dark #study-card-modal.axr .axr-kps .katex{filter:none}
#study-card-modal.axr .axr-tex{font-size:20px;overflow-x:auto;padding:8px 0;color:#FFFBEA;text-align:center}
#study-card-modal.axr .axr-tex .katex{color:#FFFBEA}
#study-card-modal.axr .axr-vars{display:grid;gap:4px;margin:8px 0 0;font-size:13.5px}
#study-card-modal.axr .axr-vars div{display:flex;gap:10px}
#study-card-modal.axr .axr-vars dt{font-family:var(--mono);color:#FFD86B;min-width:44px}
#study-card-modal.axr .axr-vars dd{margin:0;color:#DCE8E1}
#study-card-modal.axr .axr-prob{font-size:15px;line-height:1.6;margin-bottom:8px;color:#F2F0E6}
#study-card-modal.axr .axr-steps{margin:0;padding-left:1.4em;font-size:15px;line-height:1.6}
#study-card-modal.axr .axr-steps li{margin:.4em 0;color:#F2F0E6}
