/* ---------- matbaa: Belgelerim'de özetlenen belgeler ---------- */
body.acx .axp-press{position:relative;margin:0 0 22px;padding:18px 20px;border-radius:14px;background:#0D1838;background-image:radial-gradient(circle at 85% 0,rgba(47,107,255,.35),transparent 55%);color:#EEF2FF;overflow:hidden;box-shadow:0 22px 40px -28px rgba(13,24,56,.9)}
