body.acx .axp-hd small{margin-left:auto;font-family:var(--hand);font-size:19px;color:#9DB8FF}
body.acx .axp-row{display:grid;grid-template-columns:200px minmax(0,1fr);gap:22px;align-items:center}
body.acx .axp-row+.axp-row{margin-top:16px;padding-top:16px;border-top:1px dashed rgba(255,255,255,.18)}
body.acx .axp-mach{width:100%;height:auto;display:block;overflow:visible}
