body.acx .axp-mach .sheet{fill:#FFFDF8;stroke:#C3CFEC;stroke-width:1.2;animation:axpFeed 3.2s linear infinite}
body.acx .axp-mach .sheet.s2{animation-delay:-1.6s}
body.acx .axp-mach .sheet line{stroke:#9DB8FF;stroke-width:1.4}
body.acx .axp-mach .gear{fill:none;stroke:#FFD86B;stroke-width:2.4;stroke-dasharray:4 3;transform-box:fill-box;transform-origin:center;animation:axrSpin 2.4s linear infinite}
