@keyframes axpPress{0%,30%{transform:translateY(0)}45%,55%{transform:translateY(16px)}70%,100%{transform:translateY(0)}}
@keyframes axpFeed{0%{transform:translateX(-70px);opacity:0}12%{opacity:1}88%{opacity:1}100%{transform:translateX(110px);opacity:0}}
