body.acx .axp-steps li::before{content:'';position:absolute;top:0;left:0;right:0;height:5px;border-radius:3px;background:rgba(255,255,255,.14)}
body.acx .axp-steps li::after{content:'';position:absolute;top:0;left:0;height:5px;width:0;border-radius:3px;background:#FFD86B;transition:width .6s var(--ease)}
body.acx .axp-steps li.done{color:#C3CFEC}
