@keyframes axpRun{from{width:20%}to{width:85%}}
body.acx .axp-now{display:flex;align-items:center;gap:10px;font-size:13.5px;color:#C3CFEC}
body.acx .axp-now .hand{font-size:20px;color:#FFD86B}
